/*--------------------------------------------------------------------------*/

void wake_register (Wake_Func wake_func)
{
  CRITICAL ;

  C_ENTER ;
    {
      add_to_list :
        {
          Wake_Entry * wake_entry = (Wake_Entry *) os_mem_request (sizeof (Wake_Entry)) ;
    
          wake_entry -> wake_func = wake_func ;
          wake_entry -> next      = wake_list ;
    
          wake_list = wake_entry ;
        }
    }
  C_LEAVE ;
}

/*--------------------------------------------------------------------------*/

void wake_register_ready(Wake_Ready wake_func)
{
    CRITICAL ;

    C_ENTER ;
    {
      add_to_list :
        {
          Wake_Entry * wake_entry = (Wake_Entry *) os_mem_request (sizeof (Wake_Entry)) ;
    
          wake_entry -> wake_func = (Wake_Func)wake_func       ;
          wake_entry -> next      =            wake_list_ready ;
    
          wake_list_ready = wake_entry ;
        }
    }
    C_LEAVE ;
}    

/*--------------------------------------------------------------------------*/

